import React, { useState } from 'react';
import './estilos.css';

export default function App() {
  // Estado do Utilizador
  const [user, setUser] = useState({
    name: 'Carlos Silva',
    xp: 450,
    level: 3,
    badges: [
      { id: 1, title: 'Guardião da Senha', icon: '🛡️', description: 'Criou uma senha forte e ativou 2FA.' },
      { id: 2, title: 'Caçador de Phishing', icon: '🎣', description: 'Identificou e reportou um e-mail suspeito.' }
    ]
  });

  const xpPerLevel = 500; // Meta de XP para o próximo nível
  const currentLevelXP = user.xp % xpPerLevel; // XP acumulado no nível atual
  const progressPercentage = Math.min((currentLevelXP / xpPerLevel) * 100, 100); // Percentagem para a barra
  const xpNeeded = xpPerLevel - currentLevelXP; // Quanto falta para o próximo nível

  // Estado dos Treinamentos
  const [trainings, setTrainings] = useState([
    { id: 1, title: 'Conscientização sobre Phishing', xpReward: 100, status: 'Disponível', duration: '10 min' },
    { id: 2, title: 'Boas Práticas de Senhas e 2FA', xpReward: 150, status: 'Concluído', duration: '15 min' },
    { id: 3, title: 'Engenharia Social no Trabalho', xpReward: 200, status: 'Disponível', duration: '20 min' },
    { id: 4, title: 'Segurança em Redes Wi-Fi Públicas', xpReward: 120, status: 'Bloqueado', duration: '12 min' }
  ]);

  // Estado do Ranking
  const [ranking, setRanking] = useState([
    { rank: 1, name: 'Ana Souza', xp: 850, level: 5 },
    { rank: 2, name: 'Bruno Lima', xp: 620, level: 4 },
    { rank: 3, name: 'Carlos Silva (Você)', xp: 450, level: 3 },
    { rank: 4, name: 'Mariana Costa', xp: 310, level: 2 },
    { rank: 5, name: 'Pedro Alves', xp: 150, level: 1 }
  ]);

  // Função para simular a conclusão de um treino e somar XP
  const completeTraining = (id, reward) => {
    setTrainings(trainings.map(t => t.id === id ? { ...t, status: 'Concluído' } : t));
    setUser(prev => ({
      ...prev,
      xp: prev.xp + reward
    }));
  };

  return (
    <div style={{ padding: '30px', fontFamily: 'Arial, sans-serif', backgroundColor: '#0f172a', color: '#fff', minHeight: '100vh' }}>
      
      {/* Header */}
      <header style={{ marginBottom: '30px', borderBottom: '1px solid #334155', paddingBottom: '15px' }}>
        <h1 style={{ margin: 0, color: '#38bdf8' }}>🔒 Painel Gamificado de Segurança</h1>
        <p style={{ color: '#94a3b8', margin: '5px 0 0 0' }}>Bem-vindo de volta, {user.name}!</p>
      </header>

      {/* Cartões de Status */}
      <div style={{ display: 'flex', gap: '20px', marginBottom: '30px' }}>
        <div style={{ background: '#1e293b', padding: '20px', borderRadius: '8px', flex: 1 }}>
          <h3 style={{ margin: '0 0 10px 0', color: '#94a3b8' }}>Nível Atual</h3>
          <p style={{ fontSize: '28px', fontWeight: 'bold', color: '#34d399', margin: 0 }}>Nível {user.level}</p>
        </div>
        <div style={{ background: '#1e293b', padding: '20px', borderRadius: '8px', flex: 1 }}>
          <h3 style={{ margin: '0 0 10px 0', color: '#94a3b8' }}>Experiência Total</h3>
          <p style={{ fontSize: '28px', fontWeight: 'bold', color: '#fbbf24', margin: 0 }}>{user.xp} XP</p>
        </div>
      </div>

      {/* Grid Principal: Treinamentos e Ranking */}
      <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '25px', marginBottom: '30px' }}>
        
        {/* Secção de Treinamentos */}
        <section style={{ background: '#1e293b', padding: '20px', borderRadius: '8px' }}>
          <h2 style={{ marginTop: 0, color: '#38bdf8', borderBottom: '1px solid #334155', paddingBottom: '10px' }}>
             Treinamentos Disponíveis
          </h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '15px', marginTop: '15px' }}>
            {trainings.map(item => (
              <div key={item.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: '#0f172a', padding: '15px', borderRadius: '6px', border: '1px solid #334155' }}>
                <div>
                  <h4 style={{ margin: '0 0 5px 0', color: '#f8fafc', fontSize: '16px' }}>{item.title}</h4>
                  <span style={{ fontSize: '13px', color: '#94a3b8', marginRight: '15px' }}>⏱️ {item.duration}</span>
                  <span style={{ fontSize: '13px', color: '#fbbf24', fontWeight: 'bold' }}>+{item.xpReward} XP</span>
                </div>
                <div>
                  {item.status === 'Concluído' && (
                    <span style={{ padding: '6px 12px', background: '#065f46', color: '#34d399', borderRadius: '20px', fontSize: '12px', fontWeight: 'bold' }}>✓ Concluído</span>
                  )}
                  {item.status === 'Disponível' && (
                    <button 
                      onClick={() => completeTraining(item.id, item.xpReward)}
                      style={{ padding: '8px 16px', background: '#0284c7', color: '#fff', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }}
                    >
                      Iniciar
                    </button>
                  )}
                  {item.status === 'Bloqueado' && (
                    <span style={{ padding: '6px 12px', background: '#334155', color: '#94a3b8', borderRadius: '20px', fontSize: '12px' }}>🔒 Bloqueado</span>
                  )}
                </div>
              </div>
            ))}
          </div>
        </section>

        {/* Secção de Ranking */}
        <section style={{ background: '#1e293b', padding: '20px', borderRadius: '8px' }}>
          <h2 style={{ marginTop: 0, color: '#fbbf24', borderBottom: '1px solid #334155', paddingBottom: '10px' }}>
            🏆 Ranking Geral
          </h2>
          <ul style={{ listStyle: 'none', padding: 0, margin: '15px 0 0 0' }}>
            {ranking.map(player => (
              <li 
                key={player.rank} 
                style={{ 
                  display: 'flex', 
                  justifyContent: 'space-between', 
                  alignItems: 'center', 
                  padding: '12px 10px', 
                  borderBottom: '1px solid #334155',
                  backgroundColor: player.name.includes('Você') ? '#0284c722' : 'transparent',
                  borderRadius: '6px'
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                  <span style={{ fontWeight: 'bold', width: '20px', color: player.rank === 1 ? '#fbbf24' : player.rank === 2 ? '#94a3b8' : '#f8fafc' }}>
                    #{player.rank}
                  </span>
                  <span style={{ color: player.name.includes('Você') ? '#38bdf8' : '#e2e8f0', fontWeight: player.name.includes('Você') ? 'bold' : 'normal' }}>
                    {player.name}
                  </span>
                </div>
                <span style={{ fontWeight: 'bold', color: '#fbbf24', fontSize: '14px' }}>{player.xp} XP</span>
              </li>
            ))}
          </ul>
        </section>

      </div>

      {/* Secção de Conquistas */}
      <section style={{ background: '#1e293b', padding: '20px', borderRadius: '8px' }}>
        <h2 style={{ marginTop: 0, color: '#f8fafc', borderBottom: '1px solid #334155', paddingBottom: '10px' }}>
          🎖️ Minhas Conquistas
        </h2>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '15px', marginTop: '15px' }}>
          {user.badges.map(badge => (
            <div key={badge.id} style={{ display: 'flex', alignItems: 'center', background: '#0f172a', padding: '15px', borderRadius: '6px', border: '1px solid #334155' }}>
              <span style={{ fontSize: '32px', marginRight: '15px' }}>{badge.icon}</span>
              <div>
                <strong style={{ color: '#e2e8f0', display: 'block' }}>{badge.title}</strong>
                <span style={{ color: '#94a3b8', fontSize: '13px' }}>{badge.description}</span>
              </div>
            </div>
          ))}
        </div>
      </section>

    </div>
  );
}
